279	void SARBackproject::bp(xrt::aie::bo* buffers_broadcast_data_in, xrt::aie::bo* buffers_rc_in, 
280	        xrt::aie::bo* buffers_xyz_px_in, xrt::bo* buffers_img_out, int num_of_buffers) {
281	    
282	    std::vector<xrt::bo::async_handle> buff_async_hdls;
283	    
284	    // Number of target pixels for each px_demux_kern to process
285	    int px_per_demux_kern = (PULSES*RC_SAMPLES)/AIE_SWITCHES;
286	
287	    for(int buff_idx = 0; buff_idx < num_of_buffers; buff_idx++) {
288	        // Slowtime and range compressed data going to data broadcaster splicer
289	        buffers_broadcast_data_in[buff_idx].async("bpGraph[" + std::to_string(buff_idx) + "].gmio_in_st", 
290	                                                  XCL_BO_SYNC_BO_GMIO_TO_AIE, 
291	                                                  PULSES*BC_ELEMENTS*sizeof(float), 
292	                                                  0);
293	        for (int pulse_idx = 0; pulse_idx < PULSES; pulse_idx++) {
294	            buffers_rc_in[buff_idx].async("bpGraph[" + std::to_string(buff_idx) + "].gmio_in_rc", 
295	                                          XCL_BO_SYNC_BO_GMIO_TO_AIE, 
296	                                          RC_SAMPLES*sizeof(cfloat), 
297	                                          (pulse_idx*RC_SAMPLES)*sizeof(cfloat));
298	            
299	
300	            for (int sw_id=0; sw_id<AIE_SWITCHES; sw_id++) {
301	                buffers_xyz_px_in[buff_idx].async("bpGraph[" + std::to_string(buff_idx) + "].bpCluster[" + std::to_string(sw_id) + "].gmio_in_xyz_px", 
302	                                                  XCL_BO_SYNC_BO_GMIO_TO_AIE, 
303	                                                  px_per_demux_kern*sizeof(float)*3, 
304	                                                  sw_id*px_per_demux_kern*sizeof(float)*3);
305	            }
306	
307	            for (int kern_id = 0; kern_id < IMG_SOLVERS; kern_id++) {
308	                // Dump image if on last pulse, otherwise keep focusing the image
309	                if (pulse_idx == PULSES-1) {
310	                    this->m_bp_graph_hdls[buff_idx].update("bpGraph[" + std::to_string(buff_idx) + "].rtp_dump_img_in[" + std::to_string(kern_id) + "]", 1);
311	                } else {
312	                    this->m_bp_graph_hdls[buff_idx].update("bpGraph[" + std::to_string(buff_idx) + "].rtp_dump_img_in[" + std::to_string(kern_id) + "]", 0);
313	                }
314	            }
315	        }
316	        
317	        for(int sw_id = 0; sw_id < AIE_SWITCHES; sw_id++) {
318	            int pl_kern_id = buff_idx*m_instances + sw_id;
319	
320	            // Pass xrt::bo pointer to PL kernel's second arg (ddr_mem) so it can write the AIE data to it
321	            m_dma_pkt_router_run_hdls[pl_kern_id].set_arg(1, buffers_img_out[buff_idx]);
322	
323	            // Launch the PL kernel
324	            m_dma_pkt_router_run_hdls[pl_kern_id].start();
325	        }
326	
327	        // Wait for the PL kernels to finish
328	        //for(int sw_id = 0; sw_id < AIE_SWITCHES; sw_id++) {
329	        //    m_dma_pkt_router_run_hdls[buff_idx*m_instances + sw_id].wait();
330	        //}
331	
332	        // Copy results back to host from PL kernel
333	        buffers_img_out[buff_idx].sync(XCL_BO_SYNC_BO_FROM_DEVICE, PULSES*RC_SAMPLES*sizeof(cfloat), 0);
334	    }
335	}
